import pathlib, os
search_dirs=['/root','/home','/tmp','/etc','/opt','/srv','/mnt','/var/tmp']
needle='SHOPIFY_API_SECRET'
max_size=2_000_000
hits=[]
for d in search_dirs:
    p=pathlib.Path(d)
    if not p.exists():
        continue
    for f in p.rglob('*'):
        try:
            if not f.is_file():
                continue
            if f.stat().st_size>max_size:
                continue
            data=f.read_bytes()
        except Exception:
            continue
        if needle.encode() in data:
            hits.append(str(f))
print('hits', len(hits))
for h in hits[:200]:
    print(h)

